<template>
  <ul
    v-if="pagination.total_pages > 1"
    class="pagination d-flex align-items-center jy-content-center"
    :style="{ backgroundColor: style.bg }"
  >
    <li
      class="pagination__item"
      v-if="pagination.current_page > 1"
      @click="$emit('getProduct', pagination.current_page - 1)"
    >
      <span>&laquo;</span>
    </li>
    <li
      class="pagination__item"
      v-for="page in visiblePages"
      :key="page"
      :class="{ 'active': page === pagination.current_page, 'dots': page === '...' }"
      :style="styleObject"
      @click="page !== '...' && $emit('getProduct', page)"
    >
      <span>{{ page }}</span>
    </li>
    <li
      class="pagination__item"
      v-if="pagination.current_page < pagination.total_pages"
      @click="$emit('getProduct', pagination.current_page + 1)"
    >
      <span>&raquo;</span>
    </li>
  </ul>
</template>

<script>
export default {
  props: ['pagination', 'style'],
  emits: ['getProduct'],
  computed: {
    styleObject () {
      return {
        '--background': this.style.bg,
        '--background-hover': this.style.hoverBg
      }
    },
    visiblePages () {
      const currentPage = this.pagination.current_page
      const totalPages = this.pagination.total_pages
      const maxVisiblePages = 3
      const pages = []

      if (totalPages <= maxVisiblePages) {
        for (let i = 1; i <= totalPages; i++) {
          pages.push(i)
        }
      } else {
        if (currentPage <= 2) {
          for (let i = 1; i <= maxVisiblePages - 1; i++) {
            pages.push(i)
          }
          pages.push('...')
          pages.push(totalPages)
        } else if (currentPage >= totalPages - 1) {
          pages.push(1)
          pages.push('...')
          for (let i = totalPages - (maxVisiblePages - 2); i <= totalPages; i++) {
            pages.push(i)
          }
        } else {
          pages.push(1)
          pages.push('...')
          pages.push(currentPage - 1)
          pages.push(currentPage)
          pages.push(currentPage + 1)
          pages.push('...')
          pages.push(totalPages)
        }
      }

      return pages
    }
  }
}
</script>

<style lang="scss" scoped>
