  padding: 8px 0;
  cursor: pointer;

  &__prev,
  &__next {
    padding: 4px 16px;

    i {
      margin: 0 4px;
      font-size: 20px;
    }

    &:hover {
      background-color: var(--background-hover);
    }
  }

  &__prev {
    border-radius: 30px 0 0 30px;
  }

  &__next {
    border-radius: 0 30px 30px 0;
  }

  &__item {
    padding: 4px 16px;

    &.active {
      background-color: var(--background-hover);
    }

    &.dots {
      cursor: default;
    }

    &:hover {
      background-color: var(--background-hover);
    }
  }
}
</style>
